import { randomUUID, randomBytes } from 'node:crypto';
import { AppError, signupInput, loginInput } from '@crew/shared';
import { hashPassword, verifyPassword } from './passwords.js';
import { asyncRoute } from '../../http/errors.js';
import { hashToken, publicUser, requireAuth } from '../../http/middleware/auth.js';
export function registerAuth(ctx) {
  const {app,db,bus,config}=ctx;
  function session(req,res,user) {
    const token=randomBytes(32).toString('base64url');
    const time=new Date().toISOString();
    const expires=new Date(Date.now()+config.sessionDays*86400000).toISOString();
    const id=randomUUID();
    db.prepare('INSERT INTO sessions(id,user_id,token_hash,created_at,expires_at,last_used_at,user_agent) VALUES (?,?,?,?,?,?,?)').run(id,user.id,hashToken(token),time,expires,time,req.headers['user-agent']??'');
    res.cookie('crew_session',token,{httpOnly:true,sameSite:'strict',secure:false,path:'/',maxAge:config.sessionDays*86400000});
    return id;
  }
  app.post('/api/v1/auth/signup',asyncRoute(async(req,res)=>{
    const input=signupInput(req.body);
    if(db.prepare('SELECT id FROM users WHERE email=?').get(input.email))throw new AppError('CONFLICT','Email already registered',409);
    const id=randomUUID();
    const time=new Date().toISOString();
    const hash=await hashPassword(input.password);
    db.prepare('INSERT INTO users VALUES (?,?,?,?,?,?)').run(id,input.email,input.name,hash,time,time);
    const user=publicUser(db.prepare('SELECT * FROM users WHERE id=?').get(id));
    session(req,res,user);
    bus.emit({actorId:id,entityType:'user',entityId:id,action:'created',after:user});
    res.status(201).json({user});
  }));
  app.post('/api/v1/auth/login',asyncRoute(async(req,res)=>{
    const input=loginInput(req.body);
    const row=db.prepare('SELECT * FROM users WHERE email=?').get(input.email);
    if(!row||!await verifyPassword(input.password,row.password_hash))throw new AppError('UNAUTHENTICATED','Email or password is incorrect',401);
    const user=publicUser(row);
    session(req,res,user);
    bus.emit({actorId:user.id,entityType:'user',entityId:user.id,action:'login',after:{email:user.email}});
    res.json({user});
  }));
  app.post('/api/v1/auth/logout',requireAuth,(req,res)=>{
    ctx.permissions.assertSelf(req,req.user.id,'self:write');
    if(req.auth.kind==='session')db.prepare('DELETE FROM sessions WHERE id=?').run(req.auth.sessionId);
    res.clearCookie('crew_session',{path:'/'});
    bus.emit({actorId:req.user.id,entityType:'user',entityId:req.user.id,action:'logout'});
    res.json({ok:true});
  });
  app.get('/api/v1/me',requireAuth,(req,res)=>{ctx.permissions.assertSelf(req);res.json({user:req.user,auth:{kind:req.auth.kind,scopes:req.auth.scopes??null}});});
}

import {test} from 'node:test';
import assert from 'node:assert/strict';
import {testServer} from './helpers.js';
import {publicOutbox} from '../src/modules/people/outbox.js';
test('shared outbox persists all supported kinds with parsed payload and nullable ownership',async()=>{
  const s=await testServer();
  try{for(const kind of ['invite','reset','digest']){const row=s.ctx.enqueueOutbox({kind,toEmail:'A@EXAMPLE.COM',subject:'Subject',textBody:'Body',payload:{kind}});const saved=s.ctx.db.prepare('SELECT * FROM outbox WHERE id=?').get(row.id);assert.deepEqual(publicOutbox(saved),row);assert.equal(row.toEmail,'a@example.com');assert.equal(row.sentAt,null);}}
  finally{await s.close();}
});
test('shared outbox rejects unknown kinds and malformed email before insertion',async()=>{
  const s=await testServer();
  try{assert.throws(()=>s.ctx.enqueueOutbox({kind:'other'}),e=>e.status===422);assert.throws(()=>s.ctx.enqueueOutbox({kind:'digest',toEmail:'invalid'}),e=>e.status===422);assert.equal(s.ctx.db.prepare('SELECT count(*) AS n FROM outbox').get().n,0);}
  finally{await s.close();}
});

import {test,beforeEach,afterEach} from 'node:test';
import assert from 'node:assert/strict';
import {DatabaseSync} from 'node:sqlite';
import {createPermissions} from '../src/http/middleware/permissions.js';
let db,p;
beforeEach(()=>{
  db=new DatabaseSync(':memory:');
  db.exec(`CREATE TABLE memberships (org_id TEXT,user_id TEXT,role TEXT);
    CREATE TABLE projects (id TEXT,org_id TEXT);
    CREATE TABLE project_guests (project_id TEXT,user_id TEXT);
    INSERT INTO memberships VALUES ('a','owner','owner'),('a','admin','admin'),('a','member','member'),('a','guest','guest'),('b','foreign','owner');
    INSERT INTO projects VALUES ('a1','a'),('a2','a'),('b1','b');
    INSERT INTO project_guests VALUES ('a1','guest');`);
  p=createPermissions({db});
});
afterEach(()=>db.close());
const req=(id,scopes=null)=>({user:{id},auth:scopes?{kind:'token',scopes}:{kind:'session'}});
test('project guest may read and comment only on granted project',()=>{assert(p.canProject('guest','a1'));assert(p.canProject('guest','a1','comment:write'));assert.equal(p.canProject('guest','a2'),false);assert.equal(p.canProject('guest','a1','issue:write'),false);});
test('members may work in all organization projects but not manage projects',()=>{assert(p.canProject('member','a2','issue:write'));assert.equal(p.canProject('member','a2','project:manage'),false);});
test('admins and owners manage projects with explicit organization boundary',()=>{assert(p.canProject('admin','a1','project:manage'));assert(p.canProject('owner','a2','project:manage'));assert.equal(p.canProject('foreign','a1'),false);});
test('accessible project ids filter guests and outsiders',()=>{assert.deepEqual(p.projectIds('guest','a'),['a1']);assert.deepEqual(p.projectIds('owner','a'),['a1','a2']);assert.deepEqual(p.projectIds('foreign','a'),[]);});
test('assertProject returns raw project and rejects missing ids',()=>{assert.equal(p.assertProject(req('owner'),'a1').org_id,'a');assert.throws(()=>p.assertProject(req('owner'),'missing'),e=>e.status===404);});
test('API scope and user role must both permit project actions',()=>{assert.throws(()=>p.assertProject(req('owner',['project:read']),'a1','issue:write'),e=>e.status===403);assert.throws(()=>p.assertProject(req('guest',['*']),'a1','issue:write'),e=>e.status===403);assert.equal(p.assertProject(req('member',['issue:*']),'a1','issue:write').id,'a1');});
test('organization assertion rejects unauthorized and scoped access',()=>{assert.throws(()=>p.assertOrg(req('foreign'),'a'),e=>e.status===403);assert.throws(()=>p.assertOrg(req('owner',['self:*']),'a'),e=>e.status===403);assert.equal(p.assertOrg(req('admin',['org:*']),'a','org:manage').role,'admin');});
test('self assertion rejects other users and unauthenticated requests',()=>{assert.throws(()=>p.assertSelf(req('owner'),'member'),e=>e.status===403);assert.throws(()=>p.scope({user:null},'self:read'),e=>e.status===401);assert.equal(p.assertSelf(req('owner',['self:read'])).id,'owner');});
test('unknown permission never passes a wildcard token',()=>{assert.throws(()=>p.scope(req('owner',['*']),'root:admin'),e=>e.status===403);assert.equal(p.canOrg('owner','a','unknown'),false);});
